import { Pagination, type PaginationProps } from "@components/pagination";

import { useList } from "../hooks/use-list";

export const ListPagination = (props: PaginationProps) => {
  const { state, getPageCount, setPageIndex } = useList();
  const { pagination } = state;

  return (
    <Pagination
      finish={getPageCount()}
      selected={pagination.pageIndex + 1}
      onSelectedChange={(page) => setPageIndex(page - 1)}
      {...props}
    >
      {props.children || (
        <>
          <Pagination.Prev />
          <Pagination.Items />
          <Pagination.Next />
        </>
      )}
    </Pagination>
  );
};

ListPagination.displayName = "List.Pagination";
